  function dashboardData(){
    const cur=mEv('all',TD.slice(0,7)),p7=pendingBetween(7),p15=pendingBetween(15),p30=pendingBetween(30),r30=incomeBetween(30),f=forecast(30),min=f.days.reduce((a,b)=>b.bal<a.bal?b:a,{d:TD,bal:accTotal()});
    return {cur,p7,p15,p30,r30,f,min,projected:f.days.at(-1)?.bal??accTotal()};
  }
  function homeDashboard(){
    const d=dashboardData(),cards=S.v5.settings.homeCards||[];
    let h='<div class="card v5hero"><div class="row sp"><div><span class="mu">Disponível agora</span><div class="big2">'+brl(accTotal())+'</div></div><button class="ghost" onclick="v5Go(\'dashboard\')">Detalhes</button></div><div class="v5grid3">'+stat('A pagar 7 dias',brl(sum(d.p7)),'out')+stat('A pagar 30 dias',brl(sum(d.p30)),'out')+stat('Saldo projetado',brl(d.projected),d.projected<0?'out':'in')+'</div></div>';
    if(cards.includes('budgets'))h+=budgetSummaryCard();
    if(cards.includes('goals'))h+=goalSummaryCard();
    if(cards.includes('sync'))h+=`<div class="card"><div class="row sp"><div><b>Sincronização</b><div class="mu" style="font-size:12px">${escA(CLOUD_STATUS||'Local')}</div></div><span class="badge ${CLOUD_STATUS==='Sincronizado'?'okb':'warnb'}">${CLOUD_STATUS==='Sincronizado'?'✓ Nuvem':'↻ Pendente'}</span></div></div>`;
    return h;
  }
  function budgetUsed(b){
    const list=events(b.start||'2000-01-01',b.end||'2999-12-31').filter(x=>x.type==='out'&&(b.scope==='all'||x.scope===b.scope)&&(!b.cat||x.cat===b.cat));
    const actual=sum(list.filter(x=>x.date<=TD)),future=sum(list.filter(x=>x.date>TD));return{actual,future,total:actual+future};
  }
  function budgetSummaryCard(){const B=S.v5.categoryBudgets.slice(0,4);return `<div class="card"><div class="row sp"><h2>Orçamentos</h2><button class="ghost" onclick="v5Go('budgets')">Abrir</button></div>${B.length?B.map(b=>{const u=budgetUsed(b),p=pct(u.total,b.limit);return `<div class="v5budget"><div class="row sp"><span>${escA(b.name||b.cat||'Orçamento')}</span><b>${brl(u.total)} / ${brl(b.limit)}</b></div><div class="bar"><i style="width:${clamp(p,0,100)}%;background:${p>100?'var(--r)':p>85?'var(--o)':'var(--g)'}"></i></div><small class="mu">${p}% · realizado ${brl(u.actual)} · comprometido ${brl(u.future)}</small></div>`}).join(''):empty('Nenhum orçamento por categoria cadastrado.')}</div>`}
  function goalSummaryCard(){const G=S.v5.goals.filter(g=>!g.done).slice(0,3);return `<div class="card"><div class="row sp"><h2>Metas</h2><button class="ghost" onclick="v5Go('goals')">Abrir</button></div>${G.length?G.map(g=>{const p=pct(g.current,g.target);return `<div style="margin:10px 0"><div class="row sp"><span>${escA(g.name)}</span><b>${brl(g.current)} / ${brl(g.target)}</b></div><div class="bar"><i style="width:${clamp(p,0,100)}%"></i></div></div>`}).join(''):empty('Nenhuma meta ativa.')}</div>`}

  function renderDashboard(){
    const d=dashboardData(),monthly=inc(d.cur)-exp(d.cur),low=d.min;
    const body=`<div class="v5grid2">${stat('Saldo consolidado',brl(accTotal()),accTotal()<0?'out':'in')}${stat('Balanço do mês',brl(monthly),monthly<0?'out':'in')}${stat('A pagar 7 dias',brl(sum(d.p7)),'out')}${stat('A pagar 15 dias',brl(sum(d.p15)),'out')}${stat('A pagar 30 dias',brl(sum(d.p30)),'out')}${stat('Receitas 30 dias',brl(sum(d.r30)),'in')}</div>
    <div class="card"><div class="row sp"><div><h2>Projeção de caixa</h2><div class="mu">Depois de todos os lançamentos dos próximos 30 dias</div></div><b class="${d.projected<0?'out':'in'}">${brl(d.projected)}</b></div>${chart([{bal:d.f.start},...d.f.days])}<div class="row sp mu"><span>Menor saldo: ${brl(low.bal)}</span><span>${fmtDate(low.d)}</span></div></div>
    ${budgetSummaryCard()}${goalSummaryCard()}
    <div class="card"><h2>Carteiras</h2>${walletKeys().map(w=>`<div class="row sp" style="padding:7px 0;border-top:1px solid var(--ln)"><span>${escA(w.label)}</span><b class="${w.balance<0?'out':'in'}">${brl(w.balance)}</b></div>`).join('')}</div>`;
    return page('Visão gerencial','Patrimônio, compromissos e fluxo de caixa',body);
  }

  // Projetos / centros.
  function openProject(id){const x=S.v5.projects.find(v=>v.id===id);md.v5id=id||null;M(`<h2>${x?'Editar projeto':'Novo projeto/centro'}</h2>${mInput('Nome','v51',x?.name||'')}${selectInput('Tipo','v52',[['obra','Obra'],['pessoal','Pessoal'],['veiculo','Veículo'],['outros','Outros']],x?.type||'obra')}${mInput('Orçamento total (R$)','v53',x?String(x.budget||'').replace('.',','):'','text','inputmode="decimal"')}${textArea('Observações','v54',x?.note||'')}<button class="pri" onclick="saveProject()">Salvar</button>${btns()}`)}window.openProject=openProject;
  function saveProject(){const name=$('#v51').value.trim(),budget=pv($('#v53').value||'0');if(!name||isNaN(budget))return toast('Informe nome e orçamento.');if(md.v5id)v5Update('projects',md.v5id,{name,type:$('#v52').value,budget,note:$('#v54').value.trim()});else v5Add('projects',{name,type:$('#v52').value,budget,note:$('#v54').value.trim()});audit('Projeto atualizado',name,'project',md.v5id||'');save();closeM();render()}window.saveProject=saveProject;

  // Orçamentos por categoria.
  function renderBudgets(){
    const rows=S.v5.categoryBudgets.map(b=>{const u=budgetUsed(b),p=pct(u.total,b.limit);return `<div class="card"><div class="row sp"><div><b>${escA(b.name||b.cat)}</b><div class="mu">${b.scope==='obra'?'Obra':b.scope==='casa'?'Casa':'Geral'}${b.cat?' · '+escA(b.cat):''}</div></div><button class="ghost" onclick="openBudgetV5('${b.id}')">Editar</button></div><div class="bar"><i style="width:${clamp(p,0,100)}%;background:${p>100?'var(--r)':p>85?'var(--o)':'var(--g)'}"></i></div><div class="v5grid3">${stat('Realizado',brl(u.actual),'out')}${stat('Comprometido',brl(u.future),'out')}${stat('Disponível',brl(b.limit-u.total),b.limit-u.total<0?'out':'in')}</div>${p>100?'<div class="alert" style="margin-top:10px">⚠️ Orçamento ultrapassado em '+brl(u.total-b.limit)+'</div>':''}</div>`}).join('');
    return page('Orçamentos','Controle por categoria e projeto',rows||empty('Cadastre um orçamento por categoria.'),`<button class="pri" style="margin:0 0 12px" onclick="openBudgetV5()">+ Novo orçamento</button>`);
  }
  function openBudgetV5(id){const x=S.v5.categoryBudgets.find(v=>v.id===id);md.v5id=id||null;M(`<h2>${x?'Editar orçamento':'Novo orçamento'}</h2>${mInput('Nome','v51',x?.name||'')}${selectInput('Escopo','v52',[['all','Geral'],['casa','Casa'],['obra','Obra']],x?.scope||'obra')}<label>Categoria/etapa</label><select id="v53"><option value="">Todas</option>${ALL.map(c=>`<option${x?.cat===c?' selected':''}>${escA(c)}</option>`).join('')}</select>${mInput('Limite (R$)','v54',x?String(x.limit).replace('.',','):'','text','inputmode="decimal"')}${mInput('Início','v55',x?.start||TD.slice(0,4)+'-01-01','date')}${mInput('Fim','v56',x?.end||TD.slice(0,4)+'-12-31','date')}<div id="er" class="out"></div><button class="pri" onclick="saveBudgetV5()">Salvar</button>${x?`<button class="ghost out v5full" onclick="v5Delete('categoryBudgets','${x.id}')">Excluir</button>`:''}${btns()}`)}window.openBudgetV5=openBudgetV5;
  function saveBudgetV5(){const name=$('#v51').value.trim(),limit=pv($('#v54').value);if(!name||!(limit>=0))return $('#er').textContent='Informe nome e limite.';const p={name,scope:$('#v52').value,cat:$('#v53').value,limit,start:$('#v55').value,end:$('#v56').value};if(md.v5id)v5Update('categoryBudgets',md.v5id,p);else v5Add('categoryBudgets',p);audit('Orçamento salvo',name,'budget',md.v5id||'');save();closeM();render()}window.saveBudgetV5=saveBudgetV5;

  // Cartões de crédito / compras parceladas / faturas.
  function cardOutstanding(cardId){return sum(S.v5.cardCharges.filter(c=>c.cardId===cardId&&!c.paid))}
  function invoiceMonthFor(card,date){const d=new Date(date+'T12:00:00');if(d.getDate()>n(card.closingDay||31))d.setMonth(d.getMonth()+1);return ymd(d).slice(0,7)}
  function invoiceDueDate(card,m){const [y,mo]=m.split('-').map(Number);const day=Math.min(n(card.dueDay)||10,new Date(y,mo,0).getDate());return `${y}-${String(mo).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
  function renderCards(){
    const C=S.v5.cards.map(c=>{const out=cardOutstanding(c.id),avail=n(c.limit)-out,months=[...new Set(S.v5.cardCharges.filter(x=>x.cardId===c.id&&!x.paid).map(x=>x.invoiceMonth))].sort();const cur=months[0],next=months[1];const total=m=>sum(S.v5.cardCharges.filter(x=>x.cardId===c.id&&!x.paid&&x.invoiceMonth===m));return `<div class="card"><div class="row sp"><div><b>${escA(c.name)}</b><div class="mu">fecha dia ${c.closingDay} · vence dia ${c.dueDay}</div></div><button class="ghost" onclick="openCard('${c.id}')">Editar</button></div><div class="v5grid3">${stat('Limite',brl(c.limit))}${stat('Utilizado',brl(out),'out')}${stat('Disponível',brl(avail),avail<0?'out':'in')}</div>${cur?`<div class="v5invoice"><div class="row sp"><span>Fatura ${cur}</span><b>${brl(total(cur))}</b></div><small class="mu">Vence ${fmtDate(invoiceDueDate(c,cur))}</small><button class="ghost v5full" onclick="openInvoice('${c.id}','${cur}')">Ver / pagar fatura</button></div>`:''}${next?`<div class="row sp mu"><span>Próxima (${next})</span><b>${brl(total(next))}</b></div>`:''}<button class="pri" onclick="openCardPurchase('${c.id}')">+ Compra no cartão</button></div>`}).join('');
    return page('Cartões e faturas','Limite, parcelas e próximos vencimentos',C||empty('Cadastre seus cartões de crédito.'),`<button class="pri" style="margin:0 0 12px" onclick="openCard()">+ Novo cartão</button>`);
  }
  function openCard(id){const x=S.v5.cards.find(v=>v.id===id);md.v5id=id||null;M(`<h2>${x?'Editar cartão':'Novo cartão'}</h2>${mInput('Nome','v51',x?.name||'')}${mInput('Limite (R$)','v52',x?String(x.limit).replace('.',','):'','text','inputmode="decimal"')}${mInput('Dia do fechamento','v53',x?.closingDay||5,'number','min="1" max="31"')}${mInput('Dia do vencimento','v54',x?.dueDay||10,'number','min="1" max="31"')}<button class="pri" onclick="saveCard()">Salvar</button>${x?`<button class="ghost out v5full" onclick="v5Delete('cards','${x.id}')">Excluir</button>`:''}${btns()}`)}window.openCard=openCard;
  function saveCard(){const name=$('#v51').value.trim(),limit=pv($('#v52').value),closingDay=parseInt($('#v53').value),dueDay=parseInt($('#v54').value);if(!name||!(limit>0)||closingDay<1||closingDay>31||dueDay<1||dueDay>31)return toast('Confira os dados do cartão.');const p={name,limit,closingDay,dueDay};if(md.v5id)v5Update('cards',md.v5id,p);else v5Add('cards',p);audit('Cartão salvo',name,'card',md.v5id||'');save();closeM();render()}window.saveCard=saveCard;
